import HitboxManager from '../service/hitbox-manager'
import { isBlockedByQuarters } from '../service/collision'
import clock from '../service/clock'
import soundManager from '../service/sound-manager'
import resource from '../resource'
import { MAP_TYPE_WORLD, LINK_DIRECTION_EAST, LINK_DIRECTION_NORTH, LINK_DIRECTION_SOUTH, LINK_DIRECTION_WEST, LINK_ACTION_MOVE, LINK_ACTION_PICK, LINK_ACTION_HOLD_UP, LINK_ACTION_USE, LINK_ACTION_USE_ITEM_A, LINK_ACTION_USE_ITEM_B, SPRITE_LINK_PREFIX, SWORDS, SWORD_DAMAGES, SOUND_SWORD_SLASH, SOUND_LINK_HURT, OPPOSITE_DIRECTIONS, ITEM_SHIELD_MAGICAL, ITEM_BOMB, SOUND_BOMB_DROP, TILE_WIDTH, TILE_HEIGHT, SWORD_HEARTS, MAX_HEARTS, ITEM_MAGICAL_SHIELD, ITEM_WOODEN_ARROW, ARROW_WOODEN, ITEM_BLUE_CANDLE, ITEM_KEY, ITEM_BAIT, ITEM_HEART, ITEM_HEART_CONTAINER, ITEM_BLUE_RING, ITEM_RING_BLUE, ITEM_RING_RED, ITEM_LETTER, ITEM_BLUE_POTION, ITEM_RED_POTION, CAVE_POTION_SHOP, SOUND_REFILL_LOOP, ITEM_RED_CANDLE, SOUND_CANDLE, ITEM_MAGICAL_SWORD, ARROW_SILVER, BOOK_OF_MAGIC, ITEM_LADDER, ITEM_MAGICAL_KEY, ITEM_POWER_BRACELET_NORMAL, INVENTORY_MAX_BOMBS, SWORD_PALETTES, SOUND_SWORD_SHOOT, ITEM_POWER_BRACELET, ITEM_WHISTLE, NES_PIXEL, ITEM_WOODEN_BOOMERANG, ITEM_MAGICAL_BOOMERANG, ITEM_BOW, ITEM_SILVER_ARROW, ITEM_WAND, ITEM_BOOK_OF_MAGIC, ITEM_RAFT, ITEM_RED_RING, ITEM_RUPEE, ITEM_FIVE_RUPESS, ITEM_FAIRY, ITEM_CLOCK, ITEM_DUNGEON_MAP, ITEM_DUNGEON_COMPASS, ITEM_TRIFORCE_FRAGMENT, MAP_TYPES_LEVELS, SOUND_BOOMERANG, SOUND_ARROW, SOUND_MAGICAL_ROD } from '../constant'
import { Boomerang, Arrow, Magic, Bait } from './weapons'
import { tryPutLadder, canTurnOnLadder, updateLadder, leaveLadder, updateRaft, drawRaft } from './water'
import { Inventory } from './inventory'
import { createKillRecord, breakKillSeries } from './drop'
