'use strict'

import resource from '../../resource'
import { TILE_WIDTH, TILE_HEIGHT, ENEMY_LEEVER_RED, ENEMY_LEEVER_BLUE, DIRECTION_SOUTH, OPPOSITE_DIRECTIONS, NES_PIXEL } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_HURT, randomInt, pick, drawImage, isInside } from './common'
import { isBlockedByQuarters } from '../../service/collision'
import { chooseWay, avoidObstacle } from './walker'

// Sand creatures: they come out, spin around, then sink. Under the sand, they cannot be hit and
// do not hurt. The red ones come out in front of Link and rush straight on, the blue ones anywhere
const LEEVERS = {
  [ENEMY_LEEVER_RED]: { color: 'red', life: 2, contactDamage: 0.5, speed: 1, inFrontOfLink: true },
  [ENEMY_LEEVER_BLUE]: { color: 'blue', life: 4, contactDamage: 1, speed: 1, inFrontOfLink: false, turnRate: 0xa0 }
}
const MIN_UNDER_STEPS = 40
const MAX_UNDER_STEPS = 140
const RISE_STEPS = 24
const MIN_OUT_STEPS = 150
const MAX_OUT_STEPS = 260
const SPIN_FRAME_STEPS = 4
const SAND_FRAME_STEPS = 12
const TRIES = 12
// The red ones (bank 4, $8B09), measured in the ROM: two out at most, the next one 20 frames after the last (the
// first 50 frames after Link arrives). One comes out 40 NES pixels from Link the way he faces (behind him once
// in four), on the grid, facing him, and goes straight on at him, until the scenery or the edge of the screen:
// then it sinks. No time limit
const RED_DISTANCE = NES_PIXEL * 40
const RED_BEHIND_CHANCE = 1 / 4
const RED_MAX_OUT = 2
const RED_COOLDOWN = 20
const RED_FIRST_COOLDOWN = 50
const RED_GRID = TILE_WIDTH / 2
// It looks at the scenery ahead every frame, as the walkers do on the grid (bank 7, $EDFA): the bottom left quarter
// of the tile beyond the next one sideways, the row just above or below it otherwise (display pixels)
const RED_PROBES = {
  east: [[TILE_WIDTH, NES_PIXEL * 11]],
  west: [[-TILE_WIDTH, NES_PIXEL * 11]],
  north: [[0, NES_PIXEL * -5], [TILE_WIDTH / 2, NES_PIXEL * -5]],
  south: [[0, NES_PIXEL * 19], [TILE_WIDTH / 2, NES_PIXEL * 19]]
}

const STATE_UNDER = 'under'
const STATE_RISING = 'rising'
const STATE_OUT = 'out'
const STATE_SINKING = 'sinking'

class Leever extends Enemy {
  constructor (type, x, y, random = Math.random) {
    const config = LEEVERS[type]
    super(type, x, y, config, random)
    this.config = config
    this.direction = pick(random, DIRECTIONS)
    this.wait = 0
    this.setState(STATE_UNDER)
    this.wait = randomInt(random, MIN_UNDER_STEPS, MAX_UNDER_STEPS)
    this.turnFrames = 0
  }

  get isActive () {
    return [STATE_OUT, STATE_HURT].includes(this.state)
  }

  // A tile to come out at, anywhere free (blue)
  placeToRise (map) {
    for (let i = 0; i < TRIES; i++) {
      const x = map.x + randomInt(this.random, 0, map.width / TILE_WIDTH - 1) * TILE_WIDTH
      const y = map.y + randomInt(this.random, 0, map.height / TILE_HEIGHT - 1) * TILE_HEIGHT
      if (this.canStandAt(map, x, y)) {
        return { x, y }
      }
    }
    return undefined
  }

  // Where a red one comes out, and the way it goes: undefined when it has to wait (see RED_DISTANCE). Not on the
  // two top lines of the screen, nor where the scenery blocks
  placeRed (map, link) {
    let direction = DIRECTION_VECTORS[link.direction] ? link.direction : DIRECTION_SOUTH
    if (this.random() < RED_BEHIND_CHANCE) {
      direction = OPPOSITE_DIRECTIONS[direction]
    }
    const [dx, dy] = DIRECTION_VECTORS[direction]
    if (dx !== 0 && link.y - map.y < 2 * TILE_HEIGHT) {
      return undefined
    }
    const x = dx === 0 ? link.x : map.x + Math.floor((link.x - map.x + dx * RED_DISTANCE) / RED_GRID) * RED_GRID
    const y = dy === 0 ? link.y : map.y + Math.floor((link.y - map.y + dy * RED_DISTANCE) / TILE_HEIGHT) * TILE_HEIGHT
    if (y - map.y < 2 * TILE_HEIGHT || !isInside(map, x, y, this.width, this.height) || isBlockedByQuarters(map, { x, y: y + NES_PIXEL * 11, width: 1, height: 1 })) {
      return undefined
    }
    return { x, y, direction: OPPOSITE_DIRECTIONS[direction] }
  }

  // A red one going on: false at the scenery or the edge of the screen
  canRush (map) {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    if (!isInside(map, this.x + dx, this.y + dy, this.width, this.height)) {
      return false
    }
    return RED_PROBES[this.direction].every(([px, py]) => !isBlockedByQuarters(map, { x: this.x + px, y: this.y + py, width: 1, height: 1 }))
  }

  // It touched Link: it goes back (as all the enemies of the ROM)
  turnBack () {
    this.direction = OPPOSITE_DIRECTIONS[this.direction] ?? this.direction
  }

  // Out, a blue one walks on the grid like an octorok (measured in the ROM, object $0F): it turns the same way
  // (see chooseWay) and looks at the scenery as the walkers do. Walled in, it goes back into the sand
  wander (map, link) {
    if (this.turnFrames > 0) {
      this.turnFrames--
    }
    for (let i = 0; i < this.config.speed; i++) {
      if ((this.x - map.x) % TILE_WIDTH === 0 && (this.y - map.y) % TILE_HEIGHT === 0) {
        chooseWay(this, map.target ?? link, this.config)
        if (!avoidObstacle(this, map)) {
          this.setState(STATE_SINKING)
          return
        }
      }
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      this.x += dx
      this.y += dy
    }
  }

  move (map, link) {
    if (!this.config.inFrontOfLink) {
      this.wander(map, link)
      return
    }
    // Straight on at Link, from where it came out
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    for (let i = 0; i < this.config.speed; i++) {
      if (!this.canRush(map)) {
        // Back into the sand at a wall
        this.setState(STATE_SINKING)
        return
      }
      this.x += dx
      this.y += dy
    }
  }

  act (map, link) {
    switch (this.state) {
      case STATE_UNDER:
        if (this.config.inFrontOfLink) {
          this.riseRed(map, link)
        } else if (this.steps >= this.wait) {
          const place = this.placeToRise(map)
          if (!place) {
            this.setState(STATE_UNDER)
            return
          }
          this.x = place.x
          this.y = place.y
          this.setState(STATE_RISING)
        }
        break
      case STATE_RISING:
        if (this.steps >= RISE_STEPS) {
          this.setState(STATE_OUT)
          this.wait = this.config.inFrontOfLink ? Infinity : randomInt(this.random, MIN_OUT_STEPS, MAX_OUT_STEPS)
        }
        break
      case STATE_OUT:
        this.move(map, link)
        if (this.state === STATE_OUT && this.steps >= this.wait) {
          this.setState(STATE_SINKING)
        }
        break
      case STATE_SINKING:
        if (this.steps >= RISE_STEPS) {
          this.setState(STATE_UNDER)
          this.wait = randomInt(this.random, MIN_UNDER_STEPS, MAX_UNDER_STEPS)
        }
        break
    }
  }

  // When no more than one other red one is out and the last came out 20 frames ago at least
  riseRed (map, link) {
    const out = map.activeEnemies.filter(enemy => enemy.type === this.type && enemy.state !== STATE_UNDER && !enemy.isDead).length
    if ((map.leeverCooldown ?? RED_FIRST_COOLDOWN) > 0 || out >= RED_MAX_OUT) {
      return
    }
    const place = this.placeRed(map, link)
    if (!place) {
      return
    }
    this.x = place.x
    this.y = place.y
    this.direction = place.direction
    map.leeverCooldown = RED_COOLDOWN
    this.setState(STATE_RISING)
  }

  drawBody (context) {
    switch (this.state) {
      case STATE_UNDER:
        return
      case STATE_RISING:
      case STATE_SINKING: {
        // The mound grows while rising, shrinks while sinking
        const grown = Math.min(1, Math.floor(this.steps / SAND_FRAME_STEPS))
        drawImage(context, resource.getSprite('leever_sand_move'), this.state === STATE_RISING ? grown : 1 - grown, this.x, this.y, this.width, this.height)
        return
      }
    }
    drawImage(context, resource.getSprite(`leever_${this.config.color}_move`), Math.floor(this.steps / SPIN_FRAME_STEPS) % 2, this.x, this.y, this.width, this.height)
  }
}

// Once a frame: the wait between two red ones coming out
export function tickLeevers (map) {
  map.leeverCooldown = Math.max(0, (map.leeverCooldown ?? RED_FIRST_COOLDOWN) - 1)
}

export { Leever, LEEVERS }
