'use strict'

import resource from '../../resource'
import clock from '../../service/clock'
import { TILE_WIDTH, TILE_HEIGHT, TILES_PER_LINE, TILES_PER_COLUMN, NES_PIXEL } from '../../constant'
import { Enemy, STATE_HURT, pick, drawImage } from './common'
import { Fireball } from './projectile'

// Lives in the water, measured in the ROM (object $11, phases $AC): ripples 32 frames at a water tile taken at
// random, out 65 frames (it spits a fireball 16 frames after coming out), ripples again 96 frames, then the
// same at another water tile, with no wait between. The sword only hurts it out of the water
const ZORA = { life: 2, contactDamage: 0.5 }
// Before it first comes up, once Link is on the screen
const FIRST_UNDER_STEPS = 57
const EMERGE_STEPS = 32
const SURFACED_STEPS = 65
const SPIT_STEP = 16
const DIVE_STEPS = 96
// Then gone 2 frames (phase 0) before it ripples at another water tile
const UNDER_STEPS = 2
// Sprites (measured, each a tile and its mirror, sprite palette 3): the ripples, tiles $BC and $BE every 11 frames of
// the frame counter of the game (not from when it comes up); out of the water, $EC facing down when Link is lower,
// $EE facing up when he is higher
const RIPPLE_FRAME_STEPS = 11
const FRAME = 1000 / 60
// Its fireball comes out 4 NES pixels right of it
const SPIT_X = 4 * NES_PIXEL

const STATE_UNDER = 'under'
const STATE_EMERGING = 'emerging'
const STATE_SURFACED = 'surfaced'
const STATE_DIVING = 'diving'

// Water tiles: green_water, brown_water_border_north... (not the waterfalls)
const WATER = /^(green_|brown_)?water(_border_|$)/

// Water tiles of the screen
export function findWater (map) {
  const cells = []
  for (let column = 0; column < TILES_PER_LINE; column++) {
    for (let line = 0; line < TILES_PER_COLUMN; line++) {
      const name = map.getTile(column, line)?.sprite?.name ?? ''
      if (WATER.test(name)) {
        cells.push({ x: map.x + column * TILE_WIDTH, y: map.y + line * TILE_HEIGHT })
      }
    }
  }

  return cells
}

class Zora extends Enemy {
  constructor (type, water, random = Math.random) {
    const place = pick(random, water)
    super(type, place.x, place.y, ZORA, random)
    this.water = water
    this.wait = FIRST_UNDER_STEPS
    this.setState(STATE_UNDER)
    this.facingUp = false
  }

  get isActive () {
    return this.state === STATE_SURFACED || this.state === STATE_HURT
  }

  // It stays in the water when hit
  canStandAt () {
    return false
  }

  // Not pushed back (measured in the ROM): hit, it stays out for the time it had left, and does not spit again
  knockBack () {}

  hit (link, weapon) {
    const steps = this.steps
    super.hit(link, weapon)
    if (this.state === STATE_HURT) {
      this.state = STATE_SURFACED
      this.steps = steps
    }
  }

  act (map, link) {
    switch (this.state) {
      case STATE_UNDER:
        if (this.steps >= this.wait) {
          const place = pick(this.random, this.water)
          this.x = place.x
          this.y = place.y
          this.setState(STATE_EMERGING)
        }
        break
      case STATE_EMERGING:
        if (this.steps >= EMERGE_STEPS) {
          this.setState(STATE_SURFACED)
        }
        break
      case STATE_SURFACED:
        this.facingUp = link.y < this.y
        if (this.steps === SPIT_STEP) {
          map.projectiles.push(new Fireball(this.x + SPIT_X, this.y, link))
        }
        if (this.steps >= SURFACED_STEPS) {
          this.setState(STATE_DIVING)
        }
        break
      case STATE_DIVING:
        if (this.steps >= DIVE_STEPS) {
          this.setState(STATE_UNDER)
          this.wait = UNDER_STEPS
        }
        break
    }
  }

  drawBody (context) {
    switch (this.state) {
      case STATE_UNDER:
        return
      case STATE_EMERGING:
      case STATE_DIVING:
        drawImage(context, resource.getSprite('zora_water_move'), Math.floor(clock.now / FRAME / RIPPLE_FRAME_STEPS) % 2, this.x, this.y, this.width, this.height)
        return
    }
    drawImage(context, resource.getSprite('zora_move'), this.facingUp ? 1 : 0, this.x, this.y, this.width, this.height)
  }
}

export { Zora }
